    private static function bad(string $message='Dữ liệu kế hoạch xe không hợp lệ.'):never{throw new HttpError(400,$message);}
    private static function object(mixed $v,array $keys):array{if(!is_array($v)||array_diff(array_keys($v),$keys))self::bad();return $v;}
