    private static function id(mixed $v):string{return self::text($v,1,80,false);}
    private static function num(mixed $v,int $min,int $max):int{if(!is_int($v)||$v<$min||$v>$max)self::bad('Số tiền, số ghế hoặc thời gian không hợp lệ.');return $v;}
    private static function flag(mixed $v):bool{if(!is_bool($v))self::bad();return $v;}
