    private static function time(mixed $v):string{if(!is_string($v)||!preg_match('/^(?:[01][0-9]|2[0-3]):[0-5][0-9]$/D',$v))self::bad('Giờ không hợp lệ.');return $v;}
    public static function validate(mixed $raw):array
    {
        $in=self::object($raw,['enabled','qrEnabled','note','noteEn','vehicles','areas','fares','trips','requests']);$p=['enabled'=>self::flag(array_key_exists('enabled',$in)?$in['enabled']:false),'qrEnabled'=>self::flag(array_key_exists('qrEnabled',$in)?$in['qrEnabled']:false)];foreach(['note','noteEn'] as $k)if(array_key_exists($k,$in))$p[$k]=self::text($in[$k],0,3000);
        $p['vehicles']=[];foreach(self::rows($in['vehicles']??null,20) as $v){$v=self::object($v,['id','name','englishName','sharedSizes','seats','image','luggageNote']);$out=['id'=>self::id($v['id']??null),'name'=>self::text($v['name']??null,1,150)];if(array_key_exists('englishName',$v))$out['englishName']=self::text($v['englishName'],0,150);$out['seats']=self::num($v['seats']??null,1,60);$sizes=array_key_exists('sharedSizes',$v)?self::rows($v['sharedSizes'],5):($out['seats']>=6?[3,4]:($out['seats']>=2?[2]:[]));foreach($sizes as $size)self::num($size,2,$out['seats']);if(count(array_unique($sizes))!==count($sizes))self::bad('Cỡ nhóm ghép bị trùng.');if(array_key_exists('image',$v)){if($v['image']===null)$out['image']=null;else{$image=self::object($v['image'],['id','alt']);if(!is_string($image['id']??null)||!preg_match('/^[a-f0-9]{8}-[a-f0-9]{4}-[1-8][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/iD',$image['id']))self::bad('Mã ảnh không hợp lệ.');$out['image']=['id'=>$image['id'],'alt'=>self::text($image['alt']??null,0,300,false)];}}$out['luggageNote']=self::text(array_key_exists('luggageNote',$v)?$v['luggageNote']:'',0,600);$out['sharedSizes']=$sizes;$p['vehicles'][]=$out;}
        $p['areas']=[];foreach(self::rows($in['areas']??null,1000) as $v){$v=self::object($v,['id','name','central','englishName','aliases','parentId','surcharges']);$out=['id'=>self::id($v['id']??null),'name'=>self::text($v['name']??null,1,150)];if(array_key_exists('central',$v))$out['central']=self::flag($v['central']);if(array_key_exists('englishName',$v))$out['englishName']=self::text($v['englishName'],0,150);if(array_key_exists('aliases',$v))$out['aliases']=array_map(fn($a)=>self::text($a,1,150),self::rows($v['aliases'],20));if(array_key_exists('parentId',$v))$out['parentId']=self::id($v['parentId']);$charges=array_key_exists('surcharges',$v)?$v['surcharges']:[];if(!is_array($charges))self::bad();foreach($charges as $key=>$amount){if(!is_string($key)&&!is_int($key))self::bad();self::num($amount,0,100000000);}$out['surcharges']=$charges;$p['areas'][]=$out;}
        $p['fares']=[];foreach(self::rows($in['fares']??null,300) as $v){$v=self::object($v,['id','from','to','vehicleId','sharedEnabled','roundTripOnly','roundTripPrice','twoWay','privatePrice','seatPrice','durationMinutes']);$out=[];foreach(['id','from','to','vehicleId'] as $k)$out[$k]=self::id($v[$k]??null);foreach(['sharedEnabled','roundTripOnly','twoWay'] as $k)if(array_key_exists($k,$v))$out[$k]=self::flag($v[$k]);foreach(['roundTripPrice','privatePrice','seatPrice'] as $k)if($k!=='roundTripPrice'||array_key_exists($k,$v))$out[$k]=self::num($v[$k]??null,0,100000000);if(array_key_exists('durationMinutes',$v))$out['durationMinutes']=self::num($v['durationMinutes'],1,2880);$p['fares'][]=$out;}
        $p['trips']=[];foreach(self::rows($in['trips']??null,200) as $v){$v=self::object($v,['id','from','to','vehicleId','date','start','end','departure','cutoffMinutes','seatPrice','status']);$out=[];foreach(['id','from','to','vehicleId'] as $k)$out[$k]=self::id($v[$k]??null);$out['date']=StaySchema::date($v['date']??null);foreach(['start','end','departure'] as $k)$out[$k]=self::time($v[$k]??null);$out['cutoffMinutes']=self::num($v['cutoffMinutes']??null,0,1440);$out['seatPrice']=self::num($v['seatPrice']??null,0,100000000);if(!in_array($v['status']??null,['DRAFT','OPEN','CLOSED'],true))self::bad();$out['status']=$v['status'];$p['trips'][]=$out;}
        $p['requests']=[];foreach(self::rows($in['requests']??null,300) as $v){$v=self::object($v,['id','label','from','to','date','time','flexMinutes','passengers','status','tripId']);$out=[];foreach(['id','from','to'] as $k)$out[$k]=self::id($v[$k]??null);$out['label']=self::text($v['label']??null,1,150);$out['date']=StaySchema::date($v['date']??null);$out['time']=self::time($v['time']??null);if(!in_array($v['flexMinutes']??null,[0,30,60],true)||!in_array($v['status']??null,['WAITING','HELD','CONFIRMED','CANCELLED'],true))self::bad();$out['flexMinutes']=$v['flexMinutes'];$out['passengers']=self::num($v['passengers']??null,1,60);$out['status']=$v['status'];if(array_key_exists('tripId',$v))$out['tripId']=self::id($v['tripId']);$p['requests'][]=$out;}
        foreach(['vehicles','areas','fares','trips','requests'] as $section){$ids=array_column($p[$section],'id');if(count(array_unique($ids,SORT_STRING))!==count($ids))self::bad('Mã mục bị trùng.');}
        $areas=array_column($p['areas'],null,'id');$vehicles=array_column($p['vehicles'],null,'id');foreach($p['areas'] as $a){$seen=[$a['id']=>true];$parent=$a['parentId']??null;while($parent!==null){if(!isset($areas[$parent]))self::bad('Khu vực cha không tồn tại.');if(isset($seen[$parent]))self::bad('Cây khu vực bị vòng lặp.');$seen[$parent]=true;$parent=$areas[$parent]['parentId']??null;}foreach($a['surcharges'] as $vehicle=>$amount)if(!isset($vehicles[$vehicle]))self::bad('Phụ thu tham chiếu xe không tồn tại.');}
        foreach([...$p['fares'],...$p['trips'],...$p['requests']] as $r){if(!isset($areas[$r['from']],$areas[$r['to']])||$r['from']===$r['to'])self::bad('Điểm đi/đến không hợp lệ hoặc giống nhau.');if(isset($r['vehicleId'])&&!isset($vehicles[$r['vehicleId']]))self::bad('Loại xe không tồn tại.');}
        $keys=[];foreach($p['fares'] as $f){$key=json_encode([$f['from'],$f['to'],$f['vehicleId']],JSON_THROW_ON_ERROR);if(isset($keys[$key]))self::bad('Tuyến/loại xe có giá trùng.');$keys[$key]=true;if($f['twoWay']??false)foreach($p['fares'] as $other)if($other['id']!==$f['id']&&$other['vehicleId']===$f['vehicleId']&&$other['from']===$f['to']&&$other['to']===$f['from'])self::bad('Tuyến hai chiều đã gồm chiều về, không thêm giá ngược.');}
        foreach($p['trips'] as $t){if($t['start']>$t['end']||$t['end']>$t['departure'])self::bad('Giờ đón phải: bắt đầu ≤ kết thúc ≤ khởi hành.');if(self::remaining($p,$t)<0)self::bad('Chuyến ghép vượt số ghế.');}
        $trips=array_column($p['trips'],null,'id');foreach($p['requests'] as $r){if(in_array($r['status'],['HELD','CONFIRMED'],true)&&!isset($r['tripId']))self::bad('Khách giữ chỗ cần chuyến.');if($r['status']==='WAITING'&&isset($r['tripId']))self::bad('Khách chờ ghép chưa được gán chuyến.');if(isset($r['tripId'])){if(!isset($trips[$r['tripId']]))self::bad('Chuyến được gán không tồn tại.');if($r['status']!=='CANCELLED'&&!self::compatible($p,$r,$trips[$r['tripId']]))self::bad('Chuyến không phù hợp tuyến/ngày/giờ.');}}
        return $p;
    }
    public static function ancestors(array $p,string $id):array{$map=array_column($p['areas'],null,'id');$out=[];while($id!==''&&!in_array($id,$out,true)){$out[]=$id;$id=$map[$id]['parentId']??'';}return $out;}
    public static function compatible(array $p,array $r,array $t):bool{$minutes=static fn($v)=>(int)substr($v,0,2)*60+(int)substr($v,3);return $r['date']===$t['date']&&in_array($t['from'],self::ancestors($p,$r['from']),true)&&in_array($t['to'],self::ancestors($p,$r['to']),true)&&abs($minutes($r['time'])-$minutes($t['departure']))<=$r['flexMinutes'];}
    public static function remaining(array $p,array $t,?string $exclude=null):int{$v=array_column($p['vehicles'],null,'id')[$t['vehicleId']]??null;$used=0;foreach($p['requests'] as $r)if(($r['tripId']??null)===$t['id']&&$r['id']!==$exclude&&in_array($r['status'],['HELD','CONFIRMED'],true))$used+=$r['passengers'];return ($v['seats']??0)-$used;}
    public static function open(array $t,?int $now=null):bool{return $t['status']==='OPEN'&&($now??time())<(new DateTimeImmutable($t['date'].' '.$t['departure'],new DateTimeZone('Asia/Ho_Chi_Minh')))->getTimestamp()-$t['cutoffMinutes']*60;}
    public static function quotes(array $p,string $from,string $to,int $passengers):array
    {
        $starts=self::ancestors($p,$from);$ends=self::ancestors($p,$to);if(!$starts||!$ends||$from===$to)return [];$areas=array_column($p['areas'],null,'id');$out=[];foreach($p['vehicles'] as $v){if($v['seats']<$passengers)continue;$candidates=[];foreach($p['fares'] as $f){if($f['vehicleId']!==$v['id'])continue;$forward=in_array($f['from'],$starts,true)&&in_array($f['to'],$ends,true);$reverse=($f['twoWay']??false)&&in_array($f['to'],$starts,true)&&in_array($f['from'],$ends,true);if(!$forward&&!$reverse)continue;$a=$forward?$f['from']:$f['to'];$b=$forward?$f['to']:$f['from'];$candidates[]=['fare'=>$f,'from'=>$a,'to'=>$b,'score'=>array_search($a,$starts,true)+array_search($b,$ends,true)];}usort($candidates,fn($a,$b)=>$a['score']<=>$b['score']);if(!$candidates)continue;if(isset($candidates[1])&&$candidates[0]['score']===$candidates[1]['score']){$out[]=['vehicleId'=>$v['id'],'error'=>'Có nhiều giá tuyến cùng mức ưu tiên. Cần nhập giá riêng cho tuyến này.'];continue;}$c=$candidates[0];$f=$c['fare'];$traversed=[...array_slice($starts,0,array_search($c['from'],$starts,true)),...array_slice($ends,0,array_search($c['to'],$ends,true))];$extra=0;foreach($traversed as $id)$extra+=$areas[$id]['surcharges'][$v['id']]??0;$row=['vehicleId'=>$v['id'],'fareId'=>$f['id']];foreach(['sharedEnabled','roundTripOnly','roundTripPrice'] as $k)if(array_key_exists($k,$f))$row[$k]=$f[$k];$row+=['base'=>$f['privatePrice'],'surcharge'=>$extra,'total'=>$f['privatePrice']+$extra,'seatPrice'=>$f['seatPrice'],'exact'=>$c['score']===0];if(isset($f['durationMinutes']))$row['durationMinutes']=$f['durationMinutes'];$out[]=$row;}return $out;
    }
    private static function stored(array $p):array{foreach($p['areas'] as &$a)$a['surcharges']=(object)$a['surcharges'];unset($a);return $p;}
    public static function wire(array $out):array{if(isset($out['plan']))$out['plan']=self::stored($out['plan']);return $out;}
    public function read():array{$r=$this->query("SELECT data,version FROM jingo_settings WHERE id='transport-plan'")->fetch(PDO::FETCH_ASSOC);$p=self::validate($r?json_decode($r['data'],true,512,JSON_THROW_ON_ERROR):['vehicles'=>[],'areas'=>[],'fares'=>[],'trips'=>[],'requests'=>[]]);return ['plan'=>$p,'version'=>$r?(int)$r['version']:0];}
    private function hasTable(string $name):bool{return $this->query('SELECT 1 FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=?',[$name])->fetchColumn()!==false;}
    private function guardOperational(array $p):void
    {
        $vehicles=array_column($p['vehicles'],null,'id');$areas=array_column($p['areas'],null,'id');$trips=array_column($p['trips'],null,'id');$used=[];
        if($this->hasTable('jingo_ride_bookings'))foreach($this->query("SELECT visit_date,status,trip_id,data FROM jingo_ride_bookings WHERE status NOT IN ('CANCELLED','COMPLETED')")->fetchAll(PDO::FETCH_ASSOC) as $r){$d=json_decode($r['data'],true,512,JSON_THROW_ON_ERROR);if(!isset($vehicles[$d['vehicleId']??''],$areas[$d['from']??''],$areas[$d['to']??'']))throw new HttpError(409,'Xe/khu vực đang có đơn hoạt động, không thể bỏ.');if(empty($d['autoPool'])&&$r['trip_id']!==null){$t=$trips[$r['trip_id']]??null;if(!$t||$t['vehicleId']!==$d['vehicleId']||!self::compatible($p,['date'=>$r['visit_date'],'from'=>$d['from'],'to'=>$d['to'],'time'=>$d['time'],'flexMinutes'=>$d['flexMinutes']],$t))throw new HttpError(409,'Chuyến đang có khách, không thể đổi tuyến/ngày/giờ không phù hợp.');$used[$t['id']]=($used[$t['id']]??0)+(int)$d['passengers'];}}
        foreach($used as $id=>$n)if($n>$vehicles[$trips[$id]['vehicleId']]['seats'])throw new HttpError(409,'Số ghế mới nhỏ hơn khách đã ghép.');
        if($this->hasTable('jingo_ride_pools'))foreach($this->query("SELECT vehicle_id,from_id,to_id,target FROM jingo_ride_pools WHERE status NOT IN ('COMPLETED','CANCELLED')")->fetchAll(PDO::FETCH_ASSOC) as $pool)if(!isset($vehicles[$pool['vehicle_id']],$areas[$pool['from_id']],$areas[$pool['to_id']])||$vehicles[$pool['vehicle_id']]['seats']<(int)$pool['target'])throw new HttpError(409,'Xe/khu vực đang có nhóm ghép, không thể bỏ hoặc giảm ghế.');
    }
    private function savePlan(array $p,int $version,string $actor):array
    {
        $this->db->exec('SET TRANSACTION ISOLATION LEVEL READ COMMITTED');$this->db->beginTransaction();try{if(!$this->query("SELECT id FROM jingo_catalog_locks WHERE id='catalog' FOR UPDATE")->fetchColumn())throw new HttpError(503,'Chưa cài khóa danh mục.');$old=$this->read();if($old['version']!==$version)throw new HttpError(409,'Kế hoạch xe vừa thay đổi. Tải lại trước khi lưu.');$this->guardOperational($p);$this->query("INSERT INTO jingo_settings(id,data,version) VALUES ('transport-plan',?,?) ON DUPLICATE KEY UPDATE data=VALUES(data),version=VALUES(version)",[json_encode(self::stored($p),JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR),$version+1]);$this->query('INSERT INTO jingo_audit(id,admin_id,action,entity_id) VALUES (?,?,?,?)',[bin2hex(random_bytes(16)),$actor,'transport.plan.save','transport-plan']);$this->db->commit();return ['plan'=>$p,'version'=>$version+1];}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}
    }
    public function save(array $in,string $actor):array{if(count($in)!==2||array_diff(array_keys($in),['version','plan'])||!is_int($in['version']??null)||$in['version']<0||$in['version']>2147483646)self::bad();return $this->savePlan(self::validate($in['plan']??null),$in['version'],$actor);}
    public function preview(array $in):array
    {
        if(count($in)!==4||array_diff(array_keys($in),['plan','from','to','passengers']))self::bad();$p=self::validate($in['plan']??null);$from=self::id($in['from']??null);$to=self::id($in['to']??null);$passengers=self::num($in['passengers']??null,1,60);$trips=[];foreach($p['trips'] as $t)$trips[]=['id'=>$t['id'],'remaining'=>self::remaining($p,$t),'open'=>self::open($t)&&self::remaining($p,$t)>0];$suggest=[];foreach($p['requests'] as $r)if($r['status']==='WAITING')$suggest[$r['id']]=array_values(array_column(array_filter($p['trips'],fn($t)=>self::open($t)&&self::compatible($p,$r,$t)&&self::remaining($p,$t,$r['id'])>=$r['passengers']),'id'));return ['quotes'=>self::quotes($p,$from,$to,$passengers),'trips'=>$trips,'suggestions'=>(object)$suggest];
    }
